using Microsoft.AspNetCore.Authorization;
using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Data;

namespace ShipmentTracker.Endpoints;

public static class ShipmentEndpoints
{
    public static void MapShipmentEndpoints(this WebApplication app)
    {
        var group = app.MapGroup("/api/shipments");

        // Public: track by tracking number
        group.MapGet("/track/{trackingNumber}", async (string trackingNumber, ApplicationDbContext db) =>
        {
            var shipment = await db.Shipments
                .AsNoTracking()
                .FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);

            return shipment is null
                ? Results.NotFound(new { message = "Shipment not found" })
                : Results.Ok(ToDto(shipment));
        });

        // Dispatcher: list all shipments
        group.MapGet("/", [Authorize(Roles = "Dispatcher")] async (
            string? status,
            string? search,
            ApplicationDbContext db) =>
        {
            var query = db.Shipments.AsNoTracking().AsQueryable();

            if (!string.IsNullOrWhiteSpace(status) && Enum.TryParse<Data.ShipmentStatus>(status, true, out var parsedStatus))
            {
                query = query.Where(s => s.Status == parsedStatus);
            }

            if (!string.IsNullOrWhiteSpace(search))
            {
                query = query.Where(s =>
                    s.TrackingNumber.Contains(search) ||
                    s.Destination.Contains(search) ||
                    s.RecipientName.Contains(search) ||
                    s.SenderName.Contains(search));
            }

            var shipments = await query
                .OrderByDescending(s => s.CreatedAtUtc)
                .ToListAsync();

            return Results.Ok(shipments.Select(ToDto));
        });

        // Dispatcher: update shipment status
        group.MapPut("/{id:int}/status", [Authorize(Roles = "Dispatcher")] async (
            int id,
            UpdateStatusRequest request,
            ApplicationDbContext db) =>
        {
            var shipment = await db.Shipments.FindAsync(id);
            if (shipment is null)
                return Results.NotFound();

            if (!Enum.TryParse<Data.ShipmentStatus>(request.Status, true, out var newStatus))
                return Results.BadRequest(new { message = "Invalid status" });

            shipment.Status = newStatus;

            if (newStatus == Data.ShipmentStatus.Delivered)
                shipment.ActualDeliveryUtc = DateTime.UtcNow;

            await db.SaveChangesAsync();
            return Results.Ok(ToDto(shipment));
        });

        // Dispatcher: create shipment
        group.MapPost("/", [Authorize(Roles = "Dispatcher")] async (
            CreateShipmentRequest request,
            ApplicationDbContext db) =>
        {
            var shipment = new Shipment
            {
                TrackingNumber = $"SHP-{DateTime.UtcNow:yyyyMMdd}-{Random.Shared.Next(100, 999)}",
                Origin = request.Origin,
                Destination = request.Destination,
                RecipientName = request.RecipientName,
                SenderName = request.SenderName,
                WeightKg = request.WeightKg,
                Status = Data.ShipmentStatus.Pending,
                CreatedAtUtc = DateTime.UtcNow,
                EstimatedDeliveryUtc = request.EstimatedDeliveryUtc
            };

            db.Shipments.Add(shipment);
            await db.SaveChangesAsync();
            return Results.Created($"/api/shipments/{shipment.Id}", ToDto(shipment));
        });
    }

    private static ShipmentDto ToDto(Shipment s) => new()
    {
        Id = s.Id,
        TrackingNumber = s.TrackingNumber,
        Origin = s.Origin,
        Destination = s.Destination,
        Status = (Client.Models.ShipmentStatus)(int)s.Status,
        RecipientName = s.RecipientName,
        SenderName = s.SenderName,
        WeightKg = s.WeightKg,
        CreatedAtUtc = s.CreatedAtUtc,
        EstimatedDeliveryUtc = s.EstimatedDeliveryUtc,
        ActualDeliveryUtc = s.ActualDeliveryUtc
    };
}

public record UpdateStatusRequest(string Status);

public record CreateShipmentRequest(
    string Origin,
    string Destination,
    string RecipientName,
    string SenderName,
    double WeightKg,
    DateTime? EstimatedDeliveryUtc);

