+                                }
+                            </select>
+                        </td>
+                    </tr>
+                }
+            </tbody>
+        </table>
+    </div>
+}
+
+@code {
+    private List<ShipmentDto>? shipments;
+    private string searchText = "";
+    private string statusFilter = "";
+    private bool showCreateForm;
+    private bool isCreating;
+    private string? createError;
+    private CreateShipmentModel newShipment = new();
+
+    protected override async Task OnInitializedAsync()
+    {
+        await LoadShipments();
+    }
+
+    private async Task LoadShipments()
+    {
+        var url = "/api/shipments";
+        var queryParams = new List<string>();
+        if (!string.IsNullOrWhiteSpace(statusFilter)) queryParams.Add($"status={Uri.EscapeDataString(statusFilter)}");
+        if (!string.IsNullOrWhiteSpace(searchText)) queryParams.Add($"search={Uri.EscapeDataString(searchText)}");
+        if (queryParams.Any()) url += "?" + string.Join("&", queryParams);
+
+        try
+        {
+            shipments = await Http.GetFromJsonAsync<List<ShipmentDto>>(url);
+        }
+        catch
+        {
+            shipments = new();
+        }
+    }
+
+    private async Task UpdateStatus(int id, string? newStatus)
+    {
+        if (string.IsNullOrEmpty(newStatus)) return;
+        await Http.PutAsJsonAsync($"/api/shipments/{id}/status", new { Status = newStatus });
+        await LoadShipments();
+    }
+
+    private void ToggleCreateForm()
+    {
+        showCreateForm = !showCreateForm;
+        createError = null;
+        newShipment = new();
+    }
+
+    private async Task CreateShipment()
+    {
+        createError = null;
+        isCreating = true;
+
+        try
+        {
+            var response = await Http.PostAsJsonAsync("/api/shipments", new
+            {
+                newShipment.Origin,
+                newShipment.Destination,
+                newShipment.RecipientName,
+                newShipment.SenderName,
+                newShipment.WeightKg,
+                newShipment.EstimatedDeliveryUtc
+            });
+
+            if (response.IsSuccessStatusCode)
+            {
+                showCreateForm = false;
+                newShipment = new();
+                await LoadShipments();
+            }
+            else
+            {
+                createError = "Failed to create shipment.";
+            }
+        }
+        catch (Exception ex)
+        {
+            createError = $"Error: {ex.Message}";
+        }
+        finally
+        {
+            isCreating = false;
+        }
+    }
