@page "/"
@page "/track"
@page "/track/{TrackingNumber}"
@using ShipmentTracker.Client.Models
@rendermode InteractiveAuto
@inject HttpClient Http
@inject NavigationManager Nav

<PageTitle>Track Your Shipment</PageTitle>

<div class="container">
    <div class="row justify-content-center mt-4">
        <div class="col-md-8">
            <h3>🚚 Track Your Shipment</h3>
            <p class="text-muted">Enter your tracking number to see the current status and estimated delivery.</p>

            <div class="input-group mb-4">
                <input type="text" class="form-control form-control-lg"
                       placeholder="e.g. SHP-20260101-001"
                       @bind="trackingInput"
                       @onkeydown="HandleKeyDown" />
                <button class="btn btn-primary btn-lg" @onclick="TrackShipment" disabled="@isLoading">
                    @(isLoading ? "Tracking..." : "Track")
                </button>
            </div>

            @if (!string.IsNullOrEmpty(errorMessage))
            {
                <div class="alert alert-warning">
                    <strong>Not found.</strong> @errorMessage
                </div>
            }

            @if (shipment is not null)
            {
                <div class="card shadow-sm">
                    <div class="card-header d-flex justify-content-between align-items-center">
                        <h5 class="mb-0">
                            <code>@shipment.TrackingNumber</code>
                        </h5>
                        <span class="badge @GetStatusBadgeClass(shipment.Status) fs-6">@shipment.Status</span>
                    </div>
                    <div class="card-body">
                        <div class="row mb-3">
                            <div class="col-md-6">
                                <strong>From:</strong> @shipment.Origin
                            </div>
                            <div class="col-md-6">
                                <strong>To:</strong> @shipment.Destination
                            </div>
                        </div>
                        <div class="row mb-3">
                            <div class="col-md-6">
                                <strong>Sender:</strong> @shipment.SenderName
                            </div>
                            <div class="col-md-6">
                                <strong>Recipient:</strong> @shipment.RecipientName
                            </div>
                        </div>
                        <div class="row mb-3">
                            <div class="col-md-4">
                                <strong>Weight:</strong> @shipment.WeightKg kg
                            </div>
                            <div class="col-md-4">
                                <strong>Shipped:</strong> @shipment.CreatedAtUtc.ToString("MMM dd, yyyy")
                            </div>
                            <div class="col-md-4">
                                @if (shipment.ActualDeliveryUtc.HasValue)
                                {
                                    <strong>Delivered:</strong> @shipment.ActualDeliveryUtc.Value.ToString("MMM dd, yyyy h:mm tt")
                                }
                                else if (shipment.EstimatedDeliveryUtc.HasValue)
                                {
                                    <strong>Est. Delivery:</strong> @shipment.EstimatedDeliveryUtc.Value.ToString("MMM dd, yyyy")
                                }
                            </div>
                        </div>

                        <!-- Status timeline -->
                        <h6 class="mt-4">Shipment Progress</h6>
                        <div class="progress" style="height: 30px;">
                            <div class="progress-bar @GetProgressBarClass(shipment.Status)"
                                 role="progressbar"
                                 style="width: @(GetProgressPercent(shipment.Status))%"
                                 aria-valuenow="@GetProgressPercent(shipment.Status)"
                                 aria-valuemin="0" aria-valuemax="100">
                                @shipment.Status
                            </div>
                        </div>

                        <div class="d-flex justify-content-between mt-1 small text-muted">
                            <span>Pending</span>
                            <span>Picked Up</span>
                            <span>In Transit</span>
                            <span>Out for Delivery</span>
                            <span>Delivered</span>
                        </div>
                    </div>
                </div>
            }
        </div>
    </div>
</div>

@code {
    [Parameter]
    public string? TrackingNumber { get; set; }

    private string trackingInput = "";
    private ShipmentDto? shipment;
    private string? errorMessage;
    private bool isLoading;

    protected override async Task OnParametersSetAsync()
    {
        if (!string.IsNullOrWhiteSpace(TrackingNumber))
        {
            trackingInput = TrackingNumber;
            await TrackShipment();
        }
    }

    private async Task HandleKeyDown(Microsoft.AspNetCore.Components.Web.KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            await TrackShipment();
    }

    private async Task TrackShipment()
    {
        if (string.IsNullOrWhiteSpace(trackingInput)) return;

        isLoading = true;
        errorMessage = null;
        shipment = null;

        try
        {
            var response = await Http.GetAsync($"/api/shipments/track/{Uri.EscapeDataString(trackingInput.Trim())}");
            if (response.IsSuccessStatusCode)
            {
                shipment = await response.Content.ReadFromJsonAsync<ShipmentDto>();
            }
            else
            {
                errorMessage = "No shipment found with that tracking number. Please check and try again.";
            }
        }
        catch
        {
            errorMessage = "Unable to reach the server. Please try again later.";
        }
        finally
        {
            isLoading = false;
        }
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Cancelled => "bg-danger",
        _ => "bg-secondary"
    };

    private static string GetProgressBarClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Cancelled => "bg-danger",
        ShipmentStatus.Delivered => "bg-success",
        _ => "bg-primary progress-bar-striped progress-bar-animated"
    };

    private static int GetProgressPercent(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => 10,
        ShipmentStatus.PickedUp => 30,
        ShipmentStatus.InTransit => 55,
        ShipmentStatus.OutForDelivery => 80,
        ShipmentStatus.Delivered => 100,
        ShipmentStatus.Cancelled => 100,
        _ => 0
    };
}

